from copy import deepcopy
from collections import deque

class Solution:

	def shortestXYDist(self, grid, N, M):
		row = [0 for i in range(M)]
		visited = [deepcopy(row) for i in range(N)]
		(self.N, self.M) = (N, M)
		queue = deque()
		for i in range(N):
			for j in range(M):
				if grid[i][j] == 'X':
					queue.append((i, j, 0))
		return self.bfs(visited, queue, grid)

	def bfs(self, visited, queue, grid):
		min_dist = float('inf')
		while queue:
			(x, y, dist) = queue.popleft()
			if x < 0 or x >= self.N or y < 0 or (y >= self.M) or visited[x][y]:
				continue
			visited[x][y] = 1
			if grid[x][y] == 'Y':
				min_dist = min(dist, min_dist)
			queue.append((x + 1, y, dist + 1))
			queue.append((x, y + 1, dist + 1))
			queue.append((x - 1, y, dist + 1))
			queue.append((x, y - 1, dist + 1))
		return min_dist
